using System.Text.Json;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using Microsoft.EntityFrameworkCore.Storage.ValueConversion;
using Microsoft.Extensions.DependencyInjection;
using PubSoft.Auditing;
using PubSoft.Domain;

namespace PubSoft.EntityFrameworkCore.Auditing;


/// <summary>Child audit row: one entity mutation captured by the change hook.</summary>
public sealed class AuditEntityChangeRecord : IMultiTenant
{
    /// <summary>Snowflake id assigned by the writing sink (IIdGenerator); never generated by the store.</summary>
    public long Id { get; set; }
    /// <summary>Parent audit-log id.</summary>
    public long AuditLogId { get; set; }
    /// <summary>Tenant partition; null for host-scope.</summary>
    public long? TenantId { get; set; }
    /// <summary>Changed entity type name.</summary>
    public string EntityType { get; set; } = string.Empty;
    /// <summary>Changed entity id.</summary>
    public string EntityId { get; set; } = string.Empty;
    /// <summary>Create/update/delete.</summary>
    public AuditChangeKind Kind { get; set; }
    /// <summary>Capture timestamp.</summary>
    public DateTimeOffset ChangedAt { get; set; }
    /// <summary>Changed property values (JSON array).</summary>
    public string PropertiesJson { get; set; } = "[]";
    /// <summary>Parent audit row.</summary>
    public AuditLogRecord AuditLog { get; set; } = null!;
}
